INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 18, 'theory', 'Quiz: Dynamic Programming');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 0, 'Why is naive recursion for Fibonacci numbers monstrously slow?', '["Because recursion is inherently slower than a loop on every iteration", "Because subproblems overlap: the same number is recomputed many times and the call tree grows exponentially", "Because Fibonacci numbers don''t fit in the integer width", "Because the function calls itself incorrectly"]', 1, 'There are only forty distinct subproblems, but billions of calls. Overlapping subproblems plus assembling the answer from smaller ones are the hallmarks of problems dynamic programming cures.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 1, 'A robot on a grid collects coins. Why is the state "position plus the number of coins already collected" no good?', '["Because there are too many positions for a table", "Because coins can be negative", "Because a state must be numeric", "Because the number of coins collected is unknown when entering a cell: the accumulation lives in the value, not in the state"]', 3, 'Include in the state only what affects the future and is known at the moment of entry. The right state is just the position, and the value is the maximum number of coins on a path to it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 2, 'Why doesn''t the greedy rule "take the most valuable item per kilogram" solve the whole knapsack?', '["A heavy ingot may be worth more than a handful of rings yet not fit: the locally best choice ruins the global optimum", "Because floating-point division is inexact", "Because a knapsack has no fixed capacity", "Because items can''t be ordered by value"]', 0, 'This is a vaccine against careless greed. Honest dynamic programming is a table over items and capacity, where each answer picks the better of two options.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 3, 'When are two table rows enough instead of the whole table?', '["If all values in the table are positive", "If the problem can also be solved by a greedy algorithm", "If the transition looks only at the previous row", "If the table has fewer than a thousand cells"]', 2, 'A square becomes linear memory. The traversal direction is part of the solution: in the knapsack, a mistake in direction is the most popular mistake.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 18, 4, 'What is the state in Kadane''s algorithm (maximum sum of consecutive elements)?', '["The sum of all elements up to the current position", "The best piece ending exactly at the current position: extend the previous one or start over", "The maximum element of the whole array", "The length of the longest increasing piece"]', 1, 'One pass, constant memory, and the answer is the maximum over all positions. Without the idea of a state, the solution looks like a trick.');
